function groupByDate(trades) {
  const map = new Map();
  trades.forEach(t => {
    if (!map.has(t.date)) map.set(t.date, []);
    map.get(t.date).push(t);
  });
  const liveDate = LIVE_SESSION_STATE?.date;
  if (liveDate && !map.has(liveDate)) {
    map.set(liveDate, []);
  }
  // Only include days that were actually analyzed (have reasoning log entries)
  ANALYZED_DATES.forEach(d => {
    if (!map.has(d)) map.set(d, []);
  });
  return Array.from(map.entries()).map(([date, dayTrades]) => {
    const wins = dayTrades.filter(t => t.pnl_usd > 0).length;
    const losses = dayTrades.filter(t => t.pnl_usd <= 0).length;
    const pnl = dayTrades.reduce((s, t) => s + t.pnl_usd, 0);
    const hasNewRun = dayTrades.some(t => t.run === 'vwap_nav');
    const proposals = ALL_PROPOSALS.filter(p => p.date === date).length;
    return { date, trades: dayTrades.length, wins, losses, pnl, hasNewRun, proposals };
  }).sort((a, b) => a.date.localeCompare(b.date));
}

export const MOCK_SESSIONS = groupByDate(ALL_TRADES);

export function getTradesByDate(date) {
  return ALL_TRADES.filter(t => t.date === date);
}

export function getProposalsByDate(date) {
  return ALL_PROPOSALS.filter(p => p.date === date);
}

export function getReasoningsByDate(date) {
  return ALL_REASONINGS.filter(r => r.date === date);
}

function calcKpi(trades) {
  const wins = trades.filter(t => t.pnl_usd > 0);
  const losses = trades.filter(t => t.pnl_usd <= 0);
  const totalPnL = trades.reduce((s, t) => s + t.pnl_usd, 0);
  const dates = [...new Set(trades.map(t => t.date))];
  
  const avgWin = wins.length ? wins.reduce((s, t) => s + t.pnl_usd, 0) / wins.length : 0;
  const avgLoss = losses.length ? Math.abs(losses.reduce((s, t) => s + t.pnl_usd, 0) / losses.length) : 0;
  const asimmetria = avgLoss ? +(avgWin / avgLoss).toFixed(2) : 2.00;
  
  let peak = 0;
  let running = 0;
  let maxDD = 0;
  trades.forEach(t => {
    running += t.pnl_usd;
    peak = Math.max(peak, running);
    maxDD = Math.max(maxDD, peak - running);
  });
  const maxDrawdown = +(maxDD / 50000 * 100).toFixed(2);
  
  const middayRejections = ALL_PROPOSALS.filter(p => p.no_trade_reason && p.no_trade_reason.toLowerCase().includes('midday')).length;
  
  return {
    totalTrades: trades.length,
    totalDays: dates.length,
    winRate: trades.length ? +(wins.length / trades.length * 100).toFixed(1) : 0,
    totalPnL: totalPnL,
    wins: wins.length,
    losses: losses.length,
    asimmetria: asimmetria,
    maxDrawdown: maxDrawdown,
    navAlerts: ALL_PROPOSALS.filter(p => p.fabio_reasoning && p.fabio_reasoning.toLowerCase().includes('abnormal')).length,
    middayRejections: middayRejections
  };
}

export const MOCK_KPI = calcKpi(ALL_TRADES);
export const KPI_VWAP_NAV = calcKpi(ALL_TRADES.filter(t => t.run === 'vwap_nav'));
